978	// recordPriorDefectProblems は指摘 1 件の prior_defect (D8 の結果) を検査する。
979	// 書く条件は D8 に進んだかで決まる。判定フローでは、D4 で根拠を確認した指摘
980	// (premise_check.result が verified) だけが D8 に進む。required が偽の回
981	// (recordPriorDefectFirstRun の回より前の回) では、無くても報告しない。
982	func recordPriorDefectProblems(required bool, fd recordFinding) []string {
983		var problems []string
984		add := func(format string, args ...any) {
985			problems = append(problems, fmt.Sprintf(format, args...))
986		}
987		verified := fd.PremiseCheck.Result == "verified"
988		pd := fd.PriorDefect
989		if pd == nil {
990			if verified && required {
991				add("prior_defect がありません (D4 で根拠を確認した指摘は D8 で判定するので、D8 の結果を書く。この記録では、この回かそれより前の回で prior_defect を書いている)")
992			}
993			return problems
994		}
995		if !verified {
996			// D8 に進んでいない指摘の D8 の結果は、どの値でも判定の経路と矛盾するので、中身は検査しない。
997			add("prior_defect は D8 で判定した指摘 (premise_check.result が verified) にだけ書く (result %q)", fd.PremiseCheck.Result)
998			return problems
999		}
1000		lineValid := true
1001		switch pd.LineCheck {
1002		case "holds", "not-holds", "unverifiable":
1003		default:
1004			lineValid = false
1005			add("prior_defect.line_check は holds / not-holds / unverifiable のいずれか: %q", pd.LineCheck)
1006		}
1007		if pd.LineReason == "" {
1008			add("prior_defect.line_reason がありません ((1) の結果の理由。道具 lineorigin の理由と行ごとの内訳)")
1009		}
1010		if (pd.LineCheck == "holds" || pd.LineCheck == "not-holds") && pd.Base == "" {
1011			add("prior_defect.base がありません (line_check が %s なら、道具に渡した全量の起点がある)", pd.LineCheck)
1012		}
1013		switch {
1014		case pd.LineCheck == "holds":
1015			switch pd.SameDefect {
1016			case "holds", "not-holds", "unverifiable":
1017			case "":
1018				add("prior_defect.same_defect がありません (line_check が holds なら (2) を確認する)")
1019			default:
1020				add("prior_defect.same_defect は holds / not-holds / unverifiable のいずれか: %q", pd.SameDefect)
1021			}
1022			if pd.SameDefect != "" && pd.SameDefectReason == "" {
1023				add("prior_defect.same_defect_reason がありません ((2) の根拠。全量の起点の内容の該当箇所)")
1024			}
1025		case lineValid:
1026			// (1) が成り立たないか確認できなければ D8 は当たらないと決まり、(2) は確認しない。
1027			// line_check が列挙外のときは、(2) を書くべきかが決まらないので報告しない。
1028			if pd.SameDefect != "" || pd.SameDefectReason != "" {
1029				add("prior_defect.same_defect と same_defect_reason は、line_check が holds のときだけ書く (line_check %q)", pd.LineCheck)
1030			}
1031		}
1032		if priorDefectHit(pd) && fd.Verdict != "held" {
1033			add("prior_defect では D8 が当たる ((1) holds、(2) %s) のに、verdict が held ではありません (D8 が当たれば H7 の保留): %q", pd.SameDefect, fd.Verdict)
1034		}
1035		return problems
1036	}
1037	
1038	// renderFindingCells は指摘 1 件の表のセル列を返す。行を 1 つの書式文字列で
1039	// 組み立てると、テストがセル単位で分岐を検証できず、存在確認のアサーションが
1040	// 別のセルへの偶然一致で合格してしまう (実測で 3 度起きた種類の欠陥)。
1041	func renderFindingCells(fd recordFinding) []string {
1042		loc := fd.File
1043		if fd.Line > 0 {
1044			loc = fmt.Sprintf("%s:%d", fd.File, fd.Line)
1045		}
1046		aud := fd.Audience
1047		if fd.AudienceInitial != "" && fd.AudienceInitial != fd.Audience {
1048			aud = fd.AudienceInitial + " → " + fd.Audience
1049		}
1050		premise := "対象外"
1051		if fd.PremiseCheck.Stages != "none" {
1052			premise = fd.PremiseCheck.Stages + ": " + fd.PremiseCheck.Result
1053		}
1054		gates := "—"
1055		if len(fd.GatesFired) > 0 {
1056			gates = strings.Join(fd.GatesFired, ", ")
1057		}
1058		summary := recordCell(fd.Summary)
1059		if fd.Origin == "residual" {
1060			// 上流の residual をループ中に自己採択した指摘。上流の指摘と区別して読めるようにする。
1061			summary = "(residual の自己採択) " + summary
1062		}
1063		return []string{
1064			strconv.Itoa(fd.ID),
1065			"`" + recordCell(loc) + "` " + summary,
1066			recordCell(fd.Category) + " / " + recordCell(aud),
1067			recordCell(fd.Consequence.Condition) + " / " + recordCell(fd.Consequence.What) +
1068				" / " + recordCell(fd.Consequence.Detectability),
1069			premise,
1070			recordCell(gates),
1071			renderVerdictCell(fd),
1072		}
1073	}
1074	
1075	// renderVerdictCell は判定セル (判定 — 経路。D8 の結果と束ね先があれば添える) を返す。
1076	// D8 の結果は prior_defect を書いた指摘にだけ添える。過去の記録の生成サマリを変えないため。
1077	func renderVerdictCell(fd recordFinding) string {
1078		cell := recordVerdictJa(fd.Verdict) + " — " + recordCell(fd.VerdictReason)
1079		if pd := fd.PriorDefect; pd != nil {
1080			hit := "当たらない"
1081			if priorDefectHit(pd) {
1082				hit = "当たる"
1083			}
1084			cell += " (D8: " + hit + "。(1) " + recordCell(pd.LineCheck)
1085			if pd.SameDefect != "" {
1086				cell += "、(2) " + recordCell(pd.SameDefect)
1087			}
1088			cell += ")"
1089		}
1090		if fd.PlanRef != nil {
1091			// 文言はサマリに出る (変えたときの扱いは renderReviewTriageSummaryDoc の回の見出しのコメント)
1092			cell += fmt.Sprintf(" (束ね先: %d 回目の %s)", fd.PlanRef.Run, recordCell(fd.PlanRef.Problem))
1093		}
1094		return cell
1095	}
1096	
1097	// renderPlanCells は修正計画 1 件の表のセルのスライスを返す。
1098	func renderPlanCells(pl recordPlan) []string {
1099		var ids []string
1100		for _, id := range pl.FindingIDs {
1101			ids = append(ids, "#"+strconv.Itoa(id))
1102		}
1103		order := "—"
1104		if pl.Order > 0 {
1105			order = strconv.Itoa(pl.Order)
1106		}
1107		if len(pl.DependsOn) > 0 {
1108			order += " (" + recordCell(strings.Join(pl.DependsOn, ", ")) + " の後)"
1109		}

1	// judgment_flow.go は review-triage の判定フローの SSOT (judgment-flow.md) について、
2	// mermaid の図のノード ID 集合と決定表の ID 集合が 1:1 で一致するかを検査する
3	// (judgment-flow)。
4	//
5	// 図は「ノードと遷移」だけ、表は「各ノードの条件と書くもの」だけを持ち、同じ事実を
6	// 二度語らない。残るずれ方は ID 集合の不一致だけなので、そこを機械で照合する。
7	// 生成はせず、照合だけを行う。
8	package main
9	
10	import (
11		"errors"
12		"fmt"
13		"io/fs"
14		"regexp"
15		"sort"
16		"strings"
17	)
18	
19	// judgmentFlowPath は判定フローの SSOT。ファイルが存在しないときは検査を
20	// 何もしない (対象は git 追跡でなくファイルの実在で決める)。
21	//
22	// スキルがプラグインとして配られると、この SSOT はリポジトリの外 (プラグインの
23	// 展開先) に置かれ、パスは環境ごとに違う。main が CLAUDE_PLUGIN_ROOT または
24	// -judgment-flow から解決して設定する。デフォルトはリポジトリ内にスキルを直接置く
25	// 形 (プラグイン化前の配置) で、そのときだけこの値がそのまま使われる。
26	var judgmentFlowPath = ".claude/skills/review-triage/references/judgment-flow.md"
27	
28	var (
29		// judgmentFlowIDRe はノード ID の形。判定 (D)・評価 (E)・採択 (A)・保留 (H)・却下 (R)。
30		judgmentFlowIDRe = regexp.MustCompile(`\b([ADEHR]\d+)\b`)
31		// judgmentFlowTableRowRe は決定表の行 (先頭セルが ID)。パイプ前後の空白の
32		// 詰め方には依存しない。
33		judgmentFlowTableRowRe = regexp.MustCompile(`^\|\s*([ADEHR]\d+)\s*\|`)
34		// judgmentFlowQuoteRe は mermaid のラベル文字列。ID の抽出前に取り除く
35		// (ラベル内の "D1: ..." のような表示用の ID を数えないため)。
36		judgmentFlowQuoteRe = regexp.MustCompile(`"[^"]*"`)
37		// judgmentFlowColorRe は色コード。`#A12` のような大文字の短い 16 進が
38		// ID の形 ([ADEHR]\d+) に一致してしまうため、抽出前に取り除く (観点 F の反例)。
39		judgmentFlowColorRe = regexp.MustCompile(`#[0-9A-Fa-f]+`)
40		// judgmentFlowSeparatorRe は表の区切り行 (| --- | --- |)。直前の行は見出しで、
41		// 先頭セルが ID の形でも本体行として数えない。
42		judgmentFlowSeparatorRe = regexp.MustCompile(`^\s*\|(\s*:?-{3,}:?\s*\|)+\s*$`)
43	)
44	
45	// judgmentFlowDecorations は ID の出所にしない装飾行の先頭トークン。
46	var judgmentFlowDecorations = map[string]bool{
47		"style": true, "class": true, "classDef": true, "click": true, "linkStyle": true,
48	}
49	
50	// judgmentFlowProblems は図と表の ID 集合を照合する。対象は git 追跡でなく
51	// ファイルの実在で決める。追跡前の判定フローが検査の対象に入らず、0 件マッチのまま
52	// 検査が成功する種類の欠陥 (B1 と同じ) を防ぐため。
53	//
54	// ファイルが無いときの扱いは origin で分かれる。origin はパスを指定したものの
55	// 名前 (-judgment-flow / CLAUDE_PLUGIN_ROOT) で、空なら指定が無い。パスを指定する
56	// ことは「そこを検査せよ」という意思表示なので、不在は問題として報告する。指定が
57	// 無いまま不在なのはスキル未導入の正常な状態で、何もしない。1 つの入口に 2 つの
58	// 意味を担わせると、プラグインがファイルを移動・改名した時点で利用者のリポジトリの検査が
59	// 利用者に知らせずに無効になり、「実行されて合格した」と「そもそも実行されなかった」が区別できなくなる
60	// (rejection-gates.md の「診断ツールの偽陰性」)。
61	//
62	// origin を真偽値でなく名前にするのは、報告を読む人が直す先を特定できるようにする
63	// ためである。解決の経路が 2 つあるので、どちらを直せばよいかが分からないと調べ直しになる。
64	// files は他の検査とシグネチャを揃えるための引数で、使わない。
65	func judgmentFlowProblems(_ []string, readFile func(string) ([]byte, error), origin string) []string {
66		data, err := readFile(judgmentFlowPath)
67		if err != nil {
68			if errors.Is(err, fs.ErrNotExist) {
69				if origin != "" {
70					return []string{fmt.Sprintf(
71						"%s: %s が指す判定フローの SSOT が存在しません (検査が行われないまま成功するため報告する)",
72						judgmentFlowPath, origin)}
73				}
74				return nil
75			}
76			return []string{fmt.Sprintf("%s: 読み込みに失敗しました: %v", judgmentFlowPath, err)}
77		}
78	
79		var problems []string
80		diagramIDs := map[string]bool{}
81		tableIDs := map[string]int{}
82		inMermaid := false
83		hasMermaid := false
84		lines := strings.Split(string(data), "\n")
85		for i, line := range lines {
86			trimmed := strings.TrimSpace(line)
87			switch {
88			case strings.HasPrefix(trimmed, "```mermaid"):
89				inMermaid = true
90				hasMermaid = true
91				continue
92			case strings.HasPrefix(trimmed, "```"):
93				inMermaid = false
94				continue
95			}
96			if inMermaid {
97				// コメント行 (%%。ディレクティブ %%{...}%% を含む) は ID の出所にしない。
98				if strings.HasPrefix(trimmed, "%%") {
99					continue
100				}
101				// 装飾の行も ID の出所にしない。ノードを消して style 行を消し忘れた
102				// 編集ミスを、ID 照合が「図にある」と誤認しないため。先頭トークンは
103				// strings.Fields で取り出す (タブ区切りも区切りとして扱う)。
104				if fields := strings.Fields(trimmed); len(fields) > 0 && judgmentFlowDecorations[fields[0]] {
105					continue
106				}
107				stripped := judgmentFlowQuoteRe.ReplaceAllString(line, "")
108				stripped = judgmentFlowColorRe.ReplaceAllString(stripped, "")
109				for _, m := range judgmentFlowIDRe.FindAllStringSubmatch(stripped, -1) {
110					diagramIDs[m[1]] = true
111				}
112				continue
113			}
114			if m := judgmentFlowTableRowRe.FindStringSubmatch(line); m != nil {
115				// 直後が区切り行なら、この行は見出しなので、本体行として数えない。
116				if i+1 < len(lines) && judgmentFlowSeparatorRe.MatchString(lines[i+1]) {
117					continue
118				}
119				tableIDs[m[1]]++
120			}
121		}
122	
123		if !hasMermaid {
124			problems = append(problems, fmt.Sprintf("%s: mermaid の図が見つかりません (図がノードと遷移の SSOT)", judgmentFlowPath))
125		}
126		if len(tableIDs) == 0 {
127			problems = append(problems, fmt.Sprintf("%s: 決定表 (先頭セルが ID の行) が見つかりません", judgmentFlowPath))
128		}
129		if !hasMermaid || len(tableIDs) == 0 {
130			return problems
131		}
132	
133		for _, id := range sortedMapKeys(diagramIDs) {
134			if tableIDs[id] == 0 {
135				problems = append(problems, fmt.Sprintf(
136					"%s: %s は図にあるが決定表にありません (条件と書くものを表に足す)", judgmentFlowPath, id))
137			}
138		}
139		for id, n := range tableIDs {
140			if !diagramIDs[id] {
141				problems = append(problems, fmt.Sprintf(
142					"%s: %s は決定表にあるが図にありません (遷移を図に足すか行を消す)", judgmentFlowPath, id))
143			}
144			if n > 1 {
145				problems = append(problems, fmt.Sprintf(
146					"%s: %s の行が決定表で重複しています", judgmentFlowPath, id))
147			}
148		}
149		sort.Strings(problems)
150		return problems
151	}
152	
153	// sortedMapKeys はマップのキーを昇順で返す。出力の順序を入力の反復順に
154	// 依存させないため (問題の順序が実行ごとに変わると差分が読めない)。
155	func sortedMapKeys[V any](m map[string]V) []string {
156		keys := make([]string, 0, len(m))
157		for k := range m {
158			keys = append(keys, k)
159		}
160		sort.Strings(keys)
161		return keys
162	}
