286	// reviewTriageRecordProblems は記録のディレクトリの YAML を検査する。
287	// README.md は対象外。検査は (1) スキーマ (未知キー・必須キー・列挙値・参照の整合)、
288	// (2) サマリの鮮度 (YAML から生成した内容と *.md の一致)、(3) 孤児のサマリ。
289	func reviewTriageRecordProblems(files []string, readFile func(string) ([]byte, error)) []string {
290		var problems []string
291		fileSet := make(map[string]bool, len(files))
292		for _, f := range files {
293			fileSet[f] = true
294		}
295		var stems []string
296		var mds []string
297		for _, f := range files {
298			if !inReviewTriageDir(f) || path.Base(f) == "README.md" {
299				continue
300			}
301			switch {
302			case strings.HasSuffix(f, ".yaml"):
303				stems = append(stems, strings.TrimSuffix(f, ".yaml"))
304			case strings.HasSuffix(f, ".md"):
305				mds = append(mds, f)
306			}
307		}
308		sort.Strings(stems)
309		stemSet := make(map[string]bool, len(stems))
310		for _, s := range stems {
311			stemSet[s] = true
312		}
313	
314		for _, stem := range stems {
315			yf := stem + ".yaml"
316			data, err := readFile(yf)
317			if err != nil {
318				problems = append(problems, fmt.Sprintf("%s: 読み込みに失敗しました: %v", yf, err))
319				continue
320			}
321			ps, doc := recordProblemsInYAML(yf, data)
322			problems = append(problems, ps...)
323	
324			// サマリの鮮度。スキーマに問題がある間は比較しない (直せば両方直る)。
325			mdPath := stem + ".md"
326			if !fileSet[mdPath] {
327				problems = append(problems, fmt.Sprintf(
328					"%s: サマリ %s がありません (`%s` で生成してコミットする)", yf, mdPath, summaryCommand))
329				continue
330			}
331			if len(ps) > 0 || doc == nil {
332				continue
333			}
334			want := renderReviewTriageSummaryDoc(yf, doc)
335			got, err := readFile(mdPath)
336			if err != nil {
337				problems = append(problems, fmt.Sprintf("%s: 読み込みに失敗しました: %v", mdPath, err))
338				continue
339			}
340			if string(got) != want {
341				problems = append(problems, fmt.Sprintf(
342					"%s: サマリが SSOT (%s) と一致しません (`%s` で再生成する)", mdPath, yf, summaryCommand))
343			}
344		}
345	
346		sort.Strings(mds)
347		for _, md := range mds {
348			if !stemSet[strings.TrimSuffix(md, ".md")] {
349				problems = append(problems, fmt.Sprintf(
350					"%s: 対応する YAML (SSOT) がありません。記録の SSOT は <ブランチ名>.yaml で、サマリはその生成物", md))
351			}
352		}
353		return problems
354	}
