356	// recordLineCommentProblems は行内コメント (LineComment) を持つノードを検出する。
357	// YAML の素のスカラーは半角スペースに続く # 以降をコメントとして取り除くため、
358	// 引用符の無い値に # を書くと値が警告なく切り詰められる (実測で cause が「PR」だけに
359	// なった)。切り詰められた分はパーサが LineComment として保持するので、そこを見る。
360	// 生テキストの正規表現で字句規則を再現する方式では、キーの形・空白・ブロックスカラー・
361	// 値全体のコメントと境界のたびに検出漏れが生じたため (字句の形を列挙する検査は、列挙に無い形が現れるたびに検出漏れを繰り返す。既知の種類の欠陥である)。
362	// ブロックスカラーの本文の # は内容でありコメントにならないので、構造的に区別される。
363	// 行頭コメント (HeadComment) は値を壊さないため対象にしない。
364	func recordLineCommentProblems(f string, root *yaml.Node) []string {
365		var problems []string
366		var walk func(n *yaml.Node)
367		walk = func(n *yaml.Node) {
368			if n.LineComment != "" {
369				problems = append(problems, fmt.Sprintf(
370					"%s:%d: 行内コメント (%q) は使えません。YAML は ' #' 以降をコメントとして取り除き、値が警告なく切り詰められる。値に # を含めるときは引用符で囲む",
371					f, n.Line, n.LineComment))
372			}
373			for _, c := range n.Content {
374				walk(c)
375			}
376		}
377		walk(root)
378		return problems
379	}
