381	// recordProblemsInYAML は 1 ファイル分のスキーマ検査を行い、問題と (読めた場合の) 文書を返す。
382	func recordProblemsInYAML(f string, data []byte) ([]string, *recordDoc) {
383		var root yaml.Node
384		dec := yaml.NewDecoder(bytes.NewReader(data))
385		if err := dec.Decode(&root); err != nil {
386			// 空・コメントのみ・空白のみは EOF になる。生の文言では実際の状態が読めない。
387			if errors.Is(err, io.EOF) {
388				return []string{fmt.Sprintf("%s: 記録が空です (runs がありません)", f)}, nil
389			}
390			return []string{fmt.Sprintf("%s: YAML を解析できません: %v", f, err)}, nil
391		}
392		// 記録は単一ドキュメント。--- 区切りの 2 つ目以降は読まれずに消えるため、存在自体を拒否する。
393		var extra yaml.Node
394		if err := dec.Decode(&extra); err == nil {
395			return []string{fmt.Sprintf(
396				"%s: --- 区切りの 2 つ目のドキュメントがあります。記録は単一ドキュメントで、2 つ目以降は読まれず消える", f)}, nil
397		} else if !errors.Is(err, io.EOF) {
398			return []string{fmt.Sprintf("%s: 2 つ目のドキュメントの解析に失敗しました: %v", f, err)}, nil
399		}
400		if len(root.Content) == 0 ||
401			(root.Content[0].Kind == yaml.ScalarNode && root.Content[0].Tag == "!!null") {
402			// null・~・--- だけのファイルは null スカラーのルートとして解析され、
403			// EOF にも空 Content にもならない。実質的に空なので同じ文言に揃える。
404			return []string{fmt.Sprintf("%s: 記録が空です (runs がありません)", f)}, nil
405		}
406		problems := recordLineCommentProblems(f, &root)
407		problems = append(problems, recordUnknownKeyProblems(f, root.Content[0])...)
408		var doc recordDoc
409		if err := root.Decode(&doc); err != nil {
410			problems = append(problems, fmt.Sprintf("%s: スキーマに合いません: %v", f, err))
411			return problems, nil
412		}
413		problems = append(problems, recordSemanticProblems(f, &doc)...)
414		return problems, &doc
415	}
416	
417	// recordNullSilentKeys は、値を省いて null にすると他のどの検査でも失敗しない
418	// 構造キー。キーの有無をポインタの nil で見る plan_ref / investigation は、
419	// 「キーを書いて値を省いた」(書きかけ・インデントのミス) が「キーが無い」と
420	// 同一になり、書き込み元は書いたつもりのまま記録上は無い扱いになる (実測:
421	// investigation: だけの記録が検査 0 件でサマリにも出なかった)。
422	// 旧様式の recurrence も同じで、null は「無い」と同一になり、書きかけの項目が消える。
423	// consequence / premise_check の null は必須サブキーの欠落として既に報告されるので
424	// ここに含めない。重ねると 1 つの書き忘れが複数の問題になるため。
425	var recordNullSilentKeys = map[string]bool{"plan_ref": true, "prior_defect": true, "investigation": true, "verification": true, "doc_dag": true, "recurrence": true}
426	
427	// recordUnknownKeyProblems は許可キー集合との突き合わせで未知のキーと、
428	// 値の無い構造キー (recordNullSilentKeys) を列挙する。
429	// 問題が見つかっても走査を続け、他の問題の報告を妨げない。
430	func recordUnknownKeyProblems(f string, n *yaml.Node) []string {
431		var problems []string
432		var walkMap func(n *yaml.Node, kind string)
433		walkSeq := func(n *yaml.Node, kind string) {
434			if n == nil || n.Kind != yaml.SequenceNode {
435				return
436			}
437			for _, item := range n.Content {
438				walkMap(item, kind)
439			}
440		}
441		walkMap = func(n *yaml.Node, kind string) {
442			if n == nil || n.Kind != yaml.MappingNode {
443				return
444			}
445			allowed := recordAllowedKeys[kind]
446			for i := 0; i+1 < len(n.Content); i += 2 {
447				k, v := n.Content[i], n.Content[i+1]
448				if !allowed[k.Value] {
449					problems = append(problems, fmt.Sprintf(
450						"%s:%d: %sに未知のキー %q。旧いキー名の残存か、キーを書く位置のミス (上流固有の属性は attrs へ) を疑う",
451						f, k.Line, kind, k.Value))
452					continue
453				}
454				if recordNullSilentKeys[k.Value] && v.Kind == yaml.ScalarNode && v.Tag == "!!null" {
455					problems = append(problems, fmt.Sprintf(
456						"%s:%d: %s の %s に値がありません。書くなら中身を書き、書かないならキーごと消す (値の無いキーは「無い」と同じに扱われ、書いたつもりの記録が警告なく消える)",
457						f, k.Line, kind, k.Value))
458					continue
459				}
460				switch k.Value {
461				case "runs":
462					walkSeq(v, "実行")
463				case "findings":
464					walkSeq(v, "指摘")
465				case "plans":
466					walkSeq(v, "修正計画")
467				case "consequence":
468					walkMap(v, "帰結")
469				case "premise_check":
470					walkMap(v, "根拠の検証")
471				case "plan_ref":
472					walkMap(v, "束ね先")
473				case "prior_defect":
474					walkMap(v, "前からある欠陥")
475				case "investigation":
476					walkMap(v, "調査")
477				case "verification":
478					walkMap(v, "検証")
479				case "doc_dag":
480					walkMap(v, "doc-dag の確認")
481				case "recurrence":
482					walkMap(v, "検知")
483				case "evidence":
484					walkSeq(v, "根拠")
485				case "reframe":
486					walkMap(v, "捉え直し")
487				}
488			}
489		}
490		walkMap(n, "トップレベル")
491		return problems
492	}
