func TestAllowSameCommitLaterCommitChangedFile(t *testing.T) {
	r, base := branched(t)
	r.write("f.md", "a\nB\nc\n")
	r.commit("change line 2")

	o := r.check(base, "-file", "f.md", "-lines", "1", "-rev", base, "-allow-same-commit")
	wantKind(t, o, unverifiable)
